mapper.select:
SELECT

FROM RwaCertInstInvestor a WHERE 1 = 1

    AND a.userId = #{userId}


    AND a.agentName = #{agentName}


    AND a.agentRegion = #{agentRegion}


    AND a.agentPassportType = #{agentPassportType}


    AND a.agentPassportNo = #{agentPassportNo}


    AND a.agentPassportImg1 = #{agentPassportImg1}


    AND a.agentPassportImg2 = #{agentPassportImg2}


    AND a.agentPassportImg3 = #{agentPassportImg3}


    AND a.agentEmail = #{agentEmail}


    AND a.agentMobileNo = #{agentMobileNo}


    AND a.agentAuthorizationFile = #{agentAuthorizationFile}


    AND a.companyName = #{companyName}


    AND a.companyType = #{companyType}


    AND a.companyBusinessType = #{companyBusinessType}


    AND a.companyRegistrNo = #{companyRegistrNo}


    AND a.companyRegistrImg = #{companyRegistrImg}


    AND a.companyCountry = #{companyCountry}


    AND a.companyRegistrAddress = #{companyRegistrAddress}


    AND a.companyFoundedDate = #{companyFoundedDate}


    AND a.companyLicenseNumber = #{companyLicenseNumber}


    AND a.companyRegulator = #{companyRegulator}


    AND a.companyAmlCertificate = #{companyAmlCertificate}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}


    AND a.checkBy = #{checkBy}


    AND a.checkTime = #{checkTime}

limit 1
